-- The Impostor's question bank, first lot (134): general ones for any card,
-- some per theme set, a few per theme. Hand-fed like the themes: run again to
-- update the text, never to remove a question (hide it: status 'hidden').
on conflict (id) do update set
  kind = excluded.kind,
  scope = excluded.scope,
  theme_set = excluded.theme_set,
  theme_id = excluded.theme_id,
  audience = excluded.audience,
  en = excluded.en,
  es = excluded.es,
  ja = excluded.ja,
  pt = excluded.pt,
  options = excluded.options,
  spice = excluded.spice;
